// DSM CGI and session validation are generated by synopkgland. This assembly
// only wires the application adapter and the SDK's interactive File Station.
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"net/http/cgi"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	appapi "dsmapp/internal/api"
	"dsmapp/internal/gopeed"
	"dsmapp/internal/sdkcontrol"
	"dsmapp/internal/sdksettings"
	"github.com/synopackageland/syno-pkg-land-sdk/api"
	"github.com/synopackageland/syno-pkg-land-sdk/background"
	"github.com/synopackageland/syno-pkg-land-sdk/delegate"
	"github.com/synopackageland/syno-pkg-land-sdk/dsm"
	sdkfiles "github.com/synopackageland/syno-pkg-land-sdk/filestation"
)

var packageID = "SynoPkgGopeed"

// Set by synopkgland build through -ldflags -X; otherwise use the SDK request budget.
var requestTimeout = ""

var version = "dev"
var entry = ""

// "executor" when dsm-package.yaml declares portal below DSM 7.2: the executor
// registers the Application Portal entry; "on" from 7.2; empty without one.
var portal = ""

// Keep the existing linker inventory contract; delegate pins are build-time only.
var helperInventory, integrationMode, fileStation string
var delegateScope, delegateOperationsJSON, delegateDestinationsJSON, delegateLifetime, executorDigest, policyDigest string

// localExecutor is the SDK client of the package's executor; tests point
// it at a temporary package.
var localExecutor = delegate.Local

func main() {
	if os.Getenv("GATEWAY_INTERFACE") == "" && len(os.Args) == 2 && os.Args[1] == "--describe" {
		// Build-only export: assemble the same routes without running handlers.
		// This App always declares permanent destination integration.
		delegateLifetime, delegateScope = "until-revoked", "install-selected"
		delegateOperationsJSON, delegateDestinationsJSON = `["files.moveFromStaging"]`, `["save"]`
		methods, err := gopeed.DescribeRoutes(appRoutes(".")...)
		if err != nil {
			log.Fatal(err)
		}
		if err := json.NewEncoder(os.Stdout).Encode(methods); err != nil {
			log.Fatal(err)
		}
		return
	}
	if os.Getenv("GATEWAY_INTERFACE") == "" {
		fmt.Fprintln(os.Stderr, "Open Download Hub from DSM")
		os.Exit(2)
	}
	if os.Geteuid() == 0 {
		log.Fatal("refusing root CGI")
	}
	data := filepath.Join("/var/packages", packageID, "var", "gopeed")
	server, e := newAppServer(dsm.NewAuthenticator(), appRoutes(data), filepath.Dir(data))
	if e != nil {
		log.Fatal(e)
	}
	if e = cgi.Serve(cgiHandler(server)); e != nil {
		log.Fatal(e)
	}
}

func appRoutes(data string) []api.Route {
	service := gopeed.New(data)
	root := filepath.Dir(data)
	files := sdkfiles.Local(root).Routes()
	routes := append(service.Routes(), api.HandleRequest("app.status", api.AppStatusHandler(packageID, version, nil)))
	if delegateLifetime == "" {
		return append(routes, files...)
	}
	cfg, err := app.ParseDelegateConfig(app.Config{DelegateScope: delegateScope, DelegateOperationsJSON: delegateOperationsJSON, DelegateDestinationsJSON: delegateDestinationsJSON, DelegateLifetime: delegateLifetime})
	if err != nil {
		panic("invalid delegate build configuration")
	}
	// SDK 0.10.6: the client reads the package's lifecycle mailbox, so a
	// stopped or starting package is APP_STOPPED or APP_STARTING, not an
	// executor that waits for approval.
	executor := localExecutor(packageID)
	saves := &delegate.Service{ExecutorDigest: executorDigest, PolicyDigest: policyDigest, Client: executor, Store: background.NewRequestStore(filepath.Join(root, "background")), Scope: cfg.Scope, InstallDraftPath: filepath.Join(root, "delegate-install.json"), StagingDir: filepath.Join(root, "executor-staging"), Operations: cfg.Operations, Destinations: cfg.Destinations, Lifetime: cfg.Lifetime}
	service.Delegate = saves
	service.Executor = executor
	service.DestinationDelegate = saves
	routes = append(append(routes, files...), saves.Routes()...)
	return append(routes, (sdkcontrol.Config{PackageID: packageID, DataDir: root, ExecutorDigest: executorDigest, PolicyDigest: policyDigest, Portal: portal != "", PortalExecutor: portal == "executor"}).Routes()...)
}

func newAppServer(auth api.Authenticator, routes []api.Route, dataDir string) (http.Handler, error) {
	// The SDK entry gate precedes every business and SDK route policy.
	var err error
	dsm.SetBridgeFallbackDir("/var/packages/" + packageID + "/tmp")
	auth, err = dsm.NewEntryGate(sessionAuthenticator{auth}, entry, packageID, dataDir)
	if err != nil {
		return nil, err
	}
	permissions, err := appapi.Permissions()
	if err != nil {
		return nil, err
	}
	server, err := api.NewServerWithOperations(auth, appapi.Operations(), permissions, routes...)
	if err != nil {
		return nil, err
	}
	return api.WithDescription(server, auth, filepath.Join("/var/packages", packageID, "target", api.DescriptionFile)), nil
}
func cgiHandler(server http.Handler) http.Handler {
	return api.WithRequestDeadline(server, deadline())
}

func deadline() api.DeadlineOption {
	seconds, err := strconv.Atoi(requestTimeout)
	if err != nil || seconds <= 0 {
		return api.Timeout(api.DefaultRequestTimeout)
	}
	return api.Timeout(time.Duration(seconds) * time.Second)
}

type sessionAuthenticator struct{ api.Authenticator }

func (a sessionAuthenticator) Authenticate(r *http.Request) (api.Identity, error) {
	// The SDK prepares native transfer tokens before authentication.
	tokens := r.Header.Values("X-SYNO-TOKEN")
	if len(tokens) != 1 || tokens[0] == "" || len(tokens[0]) > 4096 || strings.ContainsAny(tokens[0], "\r\n\x00") {
		return api.Identity{}, api.ErrNoSession
	}
	return a.Authenticator.Authenticate(r)
}
